#!/usr/bin/env python3
from pwn import *

# Load the binary
elf = ELF('/home/ctfplayer/ctf_files/rop')
libc = ELF('/home/ctfplayer/ctf_files/libc-2.27.so')

# Print basic information
print("[*] Binary information:")
print(f"Architecture: {elf.arch}")
print(f"Entry point: {hex(elf.entry)}")
print(f"PIE: {elf.pie}")
print(f"CANARY: {elf.canary}")
print(f"NX: {elf.nx}")

# Find useful ROP gadgets
print("\n[*] Useful ROP gadgets:")
rop = ROP(elf)
try:
    pop_rdi = rop.find_gadget(['pop rdi', 'ret']).address
    print(f"pop rdi; ret: {hex(pop_rdi)}")
except:
    print("pop rdi; ret not found")

try:
    ret_gadget = rop.find_gadget(['ret']).address
    print(f"ret: {hex(ret_gadget)}")
except:
    print("ret gadget not found")

try:
    pop_rsi = rop.find_gadget(['pop rsi', 'pop r15', 'ret']).address
    print(f"pop rsi; pop r15; ret: {hex(pop_rsi)}")
except:
    print("pop rsi; pop r15; ret not found")

# Print PLT entries
print("\n[*] PLT Entries:")
for func, addr in elf.plt.items():
    print(f"{func}@plt: {hex(addr)}")

# Print GOT entries
print("\n[*] GOT Entries:")
for func, addr in elf.got.items():
    print(f"{func}@got: {hex(addr)}")

# Print symbols (to find interesting functions)
print("\n[*] Interesting symbols:")
interesting_funcs = ['system', 'execve', 'win', 'main', 'gets', 'puts', 'printf', 'scanf']
for func in interesting_funcs:
    if func in elf.symbols:
        print(f"{func}: {hex(elf.symbols[func])}")

# Print sections
print("\n[*] Sections:")
for section in elf.sections:
    try:
        print(f"{section.name}: {hex(section.header.sh_addr)} - {hex(section.header.sh_addr + section.header.sh_size)}")
    except:
        pass

# Check for strings that might be useful
print("\n[*] Useful strings:")
try:
    for section in elf.sections:
        if section.name == '.rodata':
            data = section.data()
            strings = data.split(b'\x00')
            for s in strings:
                if len(s) > 3 and all(32 <= c < 127 for c in s):  # Printable ASCII
                    print(f"String: {s.decode('latin-1')}")
except:
    print("Could not extract strings")

